begin;
create temporary table template_fixture(owner_id uuid);insert into template_fixture values(gen_random_uuid());insert into auth.users(id) select owner_id from template_fixture;
do $$begin execute format('grant usage on schema %I to authenticated',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant select on template_fixture to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from template_fixture),true);
do $$declare w uuid;s uuid;p text;d jsonb:='{"schemaVersion":2,"templateId":"local-services-v1","accent":"blue","name":"Publish Business","headline":"Approved introduction","description":"Public content","about":"","location":"","email":"hello@example.com","phone":"","services":[{"title":"Service","description":""}],"font":"modern","hours":"","sections":[{"id":"hero","type":"hero","layout":"centered","visible":true,"tone":"base","heading":"","body":"","image":"","items":[]},{"id":"contact","type":"contact","layout":"panel","visible":true,"tone":"base","heading":"","body":"","image":"","items":[]}]}'::jsonb;begin w:=(select id from public.bz_create_workspace('Expanded templates'));foreach p in array array['wellness-studio-v1','education-academy-v1','product-launch-v1'] loop d:=jsonb_set(jsonb_set(d,'{templateId}',to_jsonb(p)),'{name}',to_jsonb(p));s:=(select id from public.bz_register_business_site(w,p,'active',true,d));perform public.bz_set_business_publication(w,s,1,0,true);if (select document->>'templateId' from public.bz_read_public_business(s))<>p then raise exception 'New design lost in publication';end if;end loop;end;$$;
reset role;do $$begin if bizoveya_private.valid_business_document(jsonb_set('{"schemaVersion":2,"templateId":"local-services-v1","accent":"blue","name":"Publish Business","headline":"Approved introduction","description":"Public content","about":"","location":"","email":"hello@example.com","phone":"","services":[{"title":"Service","description":""}],"font":"modern","hours":"","sections":[{"id":"hero","type":"hero","layout":"centered","visible":true,"tone":"base","heading":"","body":"","image":"","items":[]},{"id":"contact","type":"contact","layout":"panel","visible":true,"tone":"base","heading":"","body":"","image":"","items":[]}]}'::jsonb,'{templateId}','"unknown-v1"')) then raise exception 'Unknown design accepted';end if;end;$$;rollback;
